export type PageViewEvent = {
  path: string
  userAgent: string
  referrer: string | null
  timestamp: string
}

/**
 * Sends a page view event to the analytics service.
 * If ANALYTICS_ENDPOINT is not set, it logs the event to the console.
 */
export async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    console.log('[analytics] page view', event)
    return
  }

  try {
    const res = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'page_view', ...event }),
    })
    if (!res.ok) {
      console.error(`[analytics] failed with status ${res.status}`)
    }
  } catch (error) {
    console.error('[analytics] request failed', error)
  }
}

