import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/lib/analytics'

export default async function Home() {
  // Read request data during render. Server Components cannot call
  // headers() or cookies() inside the after() callback.
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? 'unknown'
  const referrer = requestHeaders.get('referer')

  // Run the analytics call after the response is sent so it does not block rendering.
  after(async () => {
    await logPageView({
      path: '/',
      userAgent,
      referrer,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting. We&apos;re glad you&apos;re here.</p>
    </main>
  )
}

